import React from "react";

function avg(arr) {
  if (!arr.length) return 0;
  return arr.reduce((a, b) => a + b, 0) / arr.length;
}

function formatDuration(ms) {
  const m = Math.floor(ms / 60000);
  const h = Math.floor(m / 60);
  return h > 0 ? `${h}h ${m % 60}m` : `${m}m`;
}

function getWeekLogs(sleepLogs) {
  const cutoff = new Date();
  cutoff.setDate(cutoff.getDate() - 7);
  return sleepLogs.filter(l => {
    if (!l.endTime) return false;
    const s = l.startTime?.toDate ? l.startTime.toDate() : new Date(l.startTime);
    return s >= cutoff;
  });
}

function analyzeNightSleep(nightLogs) {
  if (!nightLogs.length) return null;
  const durations = nightLogs.map(l => {
    const s = l.startTime?.toDate ? l.startTime.toDate() : new Date(l.startTime);
    const e = l.endTime?.toDate ? l.endTime.toDate() : new Date(l.endTime);
    return e - s;
  });
  const bedtimes = nightLogs.map(l => {
    const s = l.startTime?.toDate ? l.startTime.toDate() : new Date(l.startTime);
    return s.getHours() * 60 + s.getMinutes();
  });
  const waketimes = nightLogs.map(l => {
    const e = l.endTime?.toDate ? l.endTime.toDate() : new Date(l.endTime);
    return e.getHours() * 60 + e.getMinutes();
  });

  return {
    avgDuration: avg(durations),
    avgBedtime: avg(bedtimes),
    avgWaketime: avg(waketimes),
    minDuration: Math.min(...durations),
    maxDuration: Math.max(...durations),
    count: nightLogs.length,
  };
}

function analyzeNapSleep(napLogs) {
  if (!napLogs.length) return null;
  const durations = napLogs.map(l => {
    const s = l.startTime?.toDate ? l.startTime.toDate() : new Date(l.startTime);
    const e = l.endTime?.toDate ? l.endTime.toDate() : new Date(l.endTime);
    return e - s;
  });
  return {
    avgDuration: avg(durations),
    count: napLogs.length,
    totalPerDay: avg(durations) * (napLogs.length / 7),
  };
}

function moodAnalysis(logs) {
  const moodCounts = {};
  logs.filter(l => l.mood).forEach(l => {
    moodCounts[l.mood] = (moodCounts[l.mood] || 0) + 1;
  });
  const sorted = Object.entries(moodCounts).sort((a, b) => b[1] - a[1]);
  return sorted;
}

function minutesToTime(mins) {
  const h = Math.floor(mins / 60) % 24;
  const m = Math.floor(mins % 60);
  const ampm = h >= 12 ? "PM" : "AM";
  const h12 = h % 12 || 12;
  return `${h12}:${m.toString().padStart(2, "0")} ${ampm}`;
}

export default function SleepInsights({ sleepLogs }) {
  const weekLogs = getWeekLogs(sleepLogs);
  const nightLogs = weekLogs.filter(l => l.type === "night");
  const napLogs = weekLogs.filter(l => l.type === "nap");

  const nightStats = analyzeNightSleep(nightLogs);
  const napStats = analyzeNapSleep(napLogs);
  const moods = moodAnalysis(weekLogs);

  // Generate insights
  const insights = [];

  if (nightStats) {
    const avgHours = nightStats.avgDuration / 3600000;
    const avgBedHour = nightStats.avgBedtime / 60;

    // Bedtime insight
    if (avgBedHour > 20.5) {
      insights.push({
        type: "tip",
        emoji: "🌙",
        title: "Try an earlier bedtime",
        body: `Camila's average bedtime is around ${minutesToTime(nightStats.avgBedtime)}. For a 7-month-old, a bedtime between 6:30–7:30 PM often leads to longer, better quality night sleep and can actually reduce early morning waking.`,
      });
    } else if (avgBedHour < 18) {
      insights.push({
        type: "tip",
        emoji: "⏰",
        title: "Bedtime may be a little early",
        body: `Camila is going to bed around ${minutesToTime(nightStats.avgBedtime)}. A slightly later bedtime of 6:30–7:30 PM can help consolidate night sleep and reduce early morning wakings.`,
      });
    } else {
      insights.push({
        type: "great",
        emoji: "✅",
        title: "Great bedtime timing!",
        body: `Camila's average bedtime of ${minutesToTime(nightStats.avgBedtime)} is right in the sweet spot for her age. Consistent timing helps set her circadian rhythm.`,
      });
    }

    // Night duration insight
    if (avgHours < 9) {
      insights.push({
        type: "tip",
        emoji: "😴",
        title: "Night sleep is on the shorter side",
        body: `Camila is averaging ${formatDuration(nightStats.avgDuration)} of night sleep. Most 7-month-olds need 10–12 hours. Make sure her last nap ends at least 3 hours before bedtime to build enough sleep pressure.`,
      });
    } else if (avgHours >= 10) {
      insights.push({
        type: "great",
        emoji: "🌟",
        title: "Excellent night sleep duration!",
        body: `Averaging ${formatDuration(nightStats.avgDuration)} of night sleep is fantastic for a 7-month-old. Keep up whatever you're doing!`,
      });
    }

    // Consistency insight
    const variability = nightStats.maxDuration - nightStats.minDuration;
    if (variability > 2 * 3600000) {
      insights.push({
        type: "tip",
        emoji: "📅",
        title: "Work on sleep consistency",
        body: `There's quite a bit of variation in Camila's night sleep length this week (${formatDuration(nightStats.minDuration)} to ${formatDuration(nightStats.maxDuration)}). A consistent bedtime routine — bath, feed, song, sleep — signals to her brain that sleep is coming.`,
      });
    }
  }

  if (napStats) {
    const avgNapMins = napStats.avgDuration / 60000;
    if (avgNapMins < 45) {
      insights.push({
        type: "tip",
        emoji: "⏱️",
        title: "Short naps detected",
        body: `Camila's naps are averaging ${Math.round(avgNapMins)} minutes. Short naps (under 45 min) can mean she's going down overtired or undertired. Try adjusting her wake windows by 15 minutes earlier or later to find the sweet spot.`,
      });
    }

    const napsPerDay = napLogs.length / 7;
    if (napsPerDay < 2) {
      insights.push({
        type: "tip",
        emoji: "☀️",
        title: "Consider adding a nap",
        body: `At 7 months, most babies need 2–3 naps per day. Camila is averaging ${napsPerDay.toFixed(1)} naps. An overtired baby actually has a harder time sleeping at night — more daytime sleep can improve nights!`,
      });
    }
  }

  // Mood insight
  if (moods.length > 0) {
    const topMood = moods[0][0];
    if (topMood === "Fussy" || topMood === "Cranky") {
      insights.push({
        type: "tip",
        emoji: "😢",
        title: "Waking up fussy — possible overtiredness",
        body: `Camila most often wakes up ${topMood.toLowerCase()} this week. This can be a sign of overtiredness or undertiredness. Try shifting her wake windows by 15 minutes and see if her mood upon waking improves.`,
      });
    } else if (topMood === "Happy" || topMood === "Calm") {
      insights.push({
        type: "great",
        emoji: "😊",
        title: "Waking up happy — great sign!",
        body: `Camila is most often waking up ${topMood.toLowerCase()} this week. This is a great sign that her sleep timing is well matched to her natural rhythms!`,
      });
    }
  }

  // General tip if not enough data
  if (weekLogs.length < 3) {
    insights.push({
      type: "info",
      emoji: "📊",
      title: "Keep logging for better insights",
      body: `Log a few more days of sleep and I'll be able to give you personalized tips based on Camila's actual patterns. The more data, the better the recommendations!`,
    });
  }

  // Always add a general tip
  insights.push({
    type: "info",
    emoji: "💡",
    title: "The 7-month sleep regression",
    body: `Many babies experience a sleep regression around 7–8 months due to developmental leaps (crawling, pulling up, language). If sleep suddenly gets worse, it's likely temporary! Stay consistent with your routine and it usually passes in 2–4 weeks.`,
  });

  return (
    <div className="tab-content">
      <h2 className="section-title">💡 Sleep Insights</h2>
      <p style={{ fontSize: "0.82rem", color: "var(--muted)", fontStyle: "italic", marginBottom: "0.5rem" }}>
        Personalized tips based on Camila's sleep data from the past 7 days
      </p>

      {insights.map((insight, i) => (
        <div key={i} className={`insight-card ${insight.type}`}>
          <div className="insight-header">
            <span className="insight-emoji">{insight.emoji}</span>
            <span className="insight-title">{insight.title}</span>
          </div>
          <p className="insight-body">{insight.body}</p>
        </div>
      ))}

      {/* Quick stats summary */}
      {(nightStats || napStats) && (
        <div className="chart-card">
          <h3 className="chart-title">This Week at a Glance</h3>
          <div className="pred-timeline">
            {nightStats && <>
              <div className="pred-row">
                <span className="pred-label">Avg night sleep</span>
                <span className="pred-value">{formatDuration(nightStats.avgDuration)}</span>
              </div>
              <div className="pred-row">
                <span className="pred-label">Avg bedtime</span>
                <span className="pred-value">{minutesToTime(nightStats.avgBedtime)}</span>
              </div>
              <div className="pred-row">
                <span className="pred-label">Avg wake time</span>
                <span className="pred-value">{minutesToTime(nightStats.avgWaketime)}</span>
              </div>
            </>}
            {napStats && <>
              <div className="pred-row">
                <span className="pred-label">Avg nap length</span>
                <span className="pred-value">{formatDuration(napStats.avgDuration)}</span>
              </div>
              <div className="pred-row">
                <span className="pred-label">Total naps this week</span>
                <span className="pred-value">{napStats.count}</span>
              </div>
            </>}
          </div>
        </div>
      )}
    </div>
  );
}
