import React, { useState } from "react";

const DIAPER_TYPES = [
  { key: "wet", label: "Wet", emoji: "💧" },
  { key: "dirty", label: "Dirty", emoji: "💩" },
  { key: "both", label: "Both", emoji: "💧💩" },
  { key: "dry", label: "Dry", emoji: "✅" },
];

function formatTime(ts) {
  const d = ts?.toDate ? ts.toDate() : new Date(ts);
  return d.toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" });
}

function formatDate(ts) {
  const d = ts?.toDate ? ts.toDate() : new Date(ts);
  const today = new Date();
  const yesterday = new Date(today);
  yesterday.setDate(today.getDate() - 1);
  if (d.toDateString() === today.toDateString()) return "Today";
  if (d.toDateString() === yesterday.toDateString()) return "Yesterday";
  return d.toLocaleDateString([], { weekday: "short", month: "short", day: "numeric" });
}

function groupByDate(logs) {
  const groups = {};
  logs.forEach(log => {
    const d = log.time?.toDate ? log.time.toDate() : new Date(log.time);
    const key = d.toDateString();
    if (!groups[key]) groups[key] = [];
    groups[key].push(log);
  });
  return groups;
}

export default function DiaperLog({ diaperLogs, onAdd, onDelete }) {
  const [type, setType] = useState("wet");
  const [time, setTime] = useState("");
  const [note, setNote] = useState("");
  const [submitting, setSubmitting] = useState(false);

  const handleAdd = async () => {
    setSubmitting(true);
    await onAdd(type, time || null, note);
    setTime("");
    setNote("");
    setSubmitting(false);
  };

  const todayStr = new Date().toDateString();
  const todayLogs = diaperLogs.filter(l => {
    const d = l.time?.toDate ? l.time.toDate() : new Date(l.time);
    return d.toDateString() === todayStr;
  });
  const todayWet = todayLogs.filter(l => l.type === "wet" || l.type === "both").length;
  const todayDirty = todayLogs.filter(l => l.type === "dirty" || l.type === "both").length;

  const grouped = groupByDate(diaperLogs);
  const dateKeys = Object.keys(grouped).sort((a, b) => new Date(b) - new Date(a));

  return (
    <div className="tab-content">
      <h2 className="section-title">🧷 Diaper Changes</h2>

      {/* Quick log buttons */}
      <div className="feeding-add-card">
        <h3 className="card-subtitle">Log a Change</h3>
        <div className="diaper-type-grid">
          {DIAPER_TYPES.map(t => (
            <button
              key={t.key}
              className={`diaper-type-btn ${type === t.key ? "selected" : ""}`}
              onClick={() => setType(t.key)}
            >
              <span className="diaper-emoji">{t.emoji}</span>
              <span className="diaper-label">{t.label}</span>
            </button>
          ))}
        </div>
        <div className="form-row" style={{ marginTop: "0.75rem" }}>
          <div style={{ flex: 1 }}>
            <div className="form-label">Time (leave blank for now)</div>
            <input
              className="form-input"
              type="datetime-local"
              value={time}
              onChange={e => setTime(e.target.value)}
            />
          </div>
        </div>
        <input
          className="note-input"
          style={{ marginTop: "0.75rem" }}
          value={note}
          onChange={e => setNote(e.target.value)}
          placeholder="Notes (e.g. rash, color) — optional"
        />
        <button className="add-btn" style={{ marginTop: "0.75rem" }} onClick={handleAdd} disabled={submitting}>
          {submitting ? "Saving…" : "➕ Log Diaper Change"}
        </button>
      </div>

      {/* Today's summary */}
      {todayLogs.length > 0 && (
        <div className="today-feeding-summary">
          <span>Today: <strong>{todayLogs.length} change{todayLogs.length !== 1 ? "s" : ""}</strong></span>
          <span>💧 {todayWet} wet · 💩 {todayDirty} dirty</span>
        </div>
      )}

      {/* History */}
      <div className="log-history">
        {diaperLogs.length === 0 && (
          <p className="empty-state">No diaper changes logged yet</p>
        )}
        {dateKeys.map(key => {
          const dayLogs = grouped[key];
          return (
            <div key={key} className="log-group">
              <div className="log-group-header">
                <span>{formatDate(dayLogs[0].time)}</span>
                <span>{dayLogs.length} change{dayLogs.length !== 1 ? "s" : ""}</span>
              </div>
              {dayLogs.map(l => {
                const t = DIAPER_TYPES.find(d => d.key === l.type);
                return (
                  <div key={l.id} className="log-item">
                    <div className="log-item-left">
                      <span className="log-icon">{t?.emoji || "🧷"}</span>
                      <div className="log-details">
                        <div className="log-main">{t?.label} · {formatTime(l.time)}</div>
                        {l.note && <div className="log-note" style={{ fontSize: "0.8rem", color: "var(--muted)", fontStyle: "italic" }}>{l.note}</div>}
                      </div>
                    </div>
                    <button className="delete-btn" onClick={() => onDelete(l.id)}>🗑️</button>
                  </div>
                );
              })}
            </div>
          );
        })}
      </div>
    </div>
  );
}
