import React from "react";

// Wake windows for 7-month-old (in minutes)
// As baby grows these naturally extend
const WAKE_WINDOWS = {
  nap1: { min: 120, max: 150, label: "2–2.5h" },   // after morning wake
  nap2: { min: 150, max: 180, label: "2.5–3h" },   // after nap 1
  nap3: { min: 150, max: 180, label: "2.5–3h" },   // after nap 2
  bedtime: { min: 180, max: 210, label: "3–3.5h" }, // before bed
};

function addMinutes(date, mins) {
  return new Date(date.getTime() + mins * 60000);
}

function formatTime(date) {
  return date.toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" });
}

function formatDuration(ms) {
  const m = Math.floor(ms / 60000);
  const h = Math.floor(m / 60);
  return h > 0 ? `${h}h ${m % 60}m` : `${m}m`;
}

function getTimeSince(date) {
  const ms = Date.now() - date.getTime();
  return formatDuration(ms);
}

export default function NapPrediction({ sleepLogs }) {
  const now = new Date();
  const todayStr = now.toDateString();

  // Get today's completed sleep events sorted by start time
  const todayLogs = sleepLogs
    .filter(l => {
      const s = l.startTime?.toDate ? l.startTime.toDate() : new Date(l.startTime);
      return s.toDateString() === todayStr;
    })
    .sort((a, b) => {
      const aT = a.startTime?.toDate ? a.startTime.toDate() : new Date(a.startTime);
      const bT = b.startTime?.toDate ? b.startTime.toDate() : new Date(b.startTime);
      return aT - bT;
    });

  // Find the last wake time (end of most recent completed sleep, or start of active sleep)
  const completedToday = todayLogs.filter(l => l.endTime);
  const activeSleep = todayLogs.find(l => !l.endTime);

  // Last wake time
  let lastWakeTime = null;
  if (activeSleep) {
    // Currently sleeping - show when she'll wake ideally
    lastWakeTime = null;
  } else if (completedToday.length > 0) {
    const last = completedToday[completedToday.length - 1];
    lastWakeTime = last.endTime?.toDate ? last.endTime.toDate() : new Date(last.endTime);
  }

  // Figure out which nap number we're on
  const napsDone = completedToday.filter(l => l.type === "nap").length;
  const nightDone = completedToday.filter(l => l.type === "night").length > 0;

  // Determine next window key
  let windowKey;
  let nextLabel;
  if (nightDone && napsDone === 0) { windowKey = "nap1"; nextLabel = "Nap 1"; }
  else if (napsDone === 1) { windowKey = "nap2"; nextLabel = "Nap 2"; }
  else if (napsDone === 2) { windowKey = "nap3"; nextLabel = "Nap 3"; }
  else if (napsDone >= 3) { windowKey = "bedtime"; nextLabel = "Bedtime"; }
  else { windowKey = "nap1"; nextLabel = "Nap 1"; }

  const window = WAKE_WINDOWS[windowKey];

  // Calculate prediction
  let prediction = null;
  if (lastWakeTime) {
    const earliest = addMinutes(lastWakeTime, window.min);
    const latest = addMinutes(lastWakeTime, window.max);
    const awakeMs = now - lastWakeTime;
    const awakeMin = Math.floor(awakeMs / 60000);
    const readyIn = window.min - awakeMin;

    prediction = { earliest, latest, awakeMin, readyIn, lastWakeTime };
  }

  const isOverdue = prediction && prediction.readyIn < -15;
  const isReady = prediction && prediction.readyIn <= 0 && !isOverdue;
  const isSoon = prediction && prediction.readyIn > 0 && prediction.readyIn <= 20;

  return (
    <div className="chart-card" style={{ marginBottom: 0 }}>
      <h3 className="chart-title">🔮 Next Nap Prediction</h3>
      <p style={{ fontSize: "0.75rem", color: "var(--muted)", fontStyle: "italic", marginBottom: "1rem" }}>
        Based on typical wake windows for a 7-month-old
      </p>

      {activeSleep ? (
        <div className="prediction-status sleeping">
          <div className="pred-emoji">😴</div>
          <div className="pred-text">Camila is sleeping right now!</div>
          <div className="pred-sub">Next wake window prediction will appear when she wakes up.</div>
        </div>
      ) : !prediction ? (
        <div className="prediction-status neutral">
          <div className="pred-emoji">🌅</div>
          <div className="pred-text">Log a sleep or night wake to see predictions</div>
          <div className="pred-sub">Once you log a wake time, I'll predict her next nap window.</div>
        </div>
      ) : (
        <div>
          <div className={`prediction-status ${isOverdue ? "overdue" : isReady ? "ready" : isSoon ? "soon" : "waiting"}`}>
            <div className="pred-emoji">
              {isOverdue ? "⚠️" : isReady ? "✅" : isSoon ? "⏰" : "⏳"}
            </div>
            <div className="pred-text">
              {isOverdue
                ? `${nextLabel} is overdue!`
                : isReady
                ? `${nextLabel} window is open!`
                : isSoon
                ? `${nextLabel} coming up soon`
                : `${nextLabel} in about ${prediction.readyIn} min`}
            </div>
            <div className="pred-sub">
              Awake for {formatDuration(prediction.awakeMin * 60000)} · Ideal window: {window.label}
            </div>
          </div>

          <div className="pred-timeline">
            <div className="pred-row">
              <span className="pred-label">Last wake</span>
              <span className="pred-value">{formatTime(prediction.lastWakeTime)}</span>
            </div>
            <div className="pred-row">
              <span className="pred-label">Earliest {nextLabel}</span>
              <span className="pred-value" style={{ color: "var(--green)" }}>{formatTime(prediction.earliest)}</span>
            </div>
            <div className="pred-row">
              <span className="pred-label">Latest {nextLabel}</span>
              <span className="pred-value" style={{ color: "var(--gold)" }}>{formatTime(prediction.latest)}</span>
            </div>
          </div>

          {/* Naps done today */}
          <div className="naps-done">
            {["Nap 1", "Nap 2", "Nap 3"].map((n, i) => (
              <div key={n} className={`nap-dot ${napsDone > i ? "done" : napsDone === i ? "next" : ""}`}>
                <div className="nap-dot-circle" />
                <span>{n}</span>
              </div>
            ))}
            <div className={`nap-dot ${windowKey === "bedtime" ? "next" : ""}`}>
              <div className="nap-dot-circle" />
              <span>Bed</span>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}
